DROP TABLE IF EXISTS ${com_schema}.temp_t_mhbos_m_client_identification_info_step1;

CREATE TABLE ${com_schema}.temp_t_mhbos_m_client_identification_info_step1 AS
SELECT
  id.client_no,
  (
    id.primary_identification_type_flag || id.primary_identification_no_flag || id.secondary_identification_type_flag || id.secondary_identification_no_flag || cn.client_name_flag || cn.client_name1_flag || cn.client_name2_flag || cn.client_name3_flag || tel.mobile_no_flag || tel.fax_no_flag || tel.tel_no_home_flag || tel.tel_no_office_flag || dob.date_of_birth_flag || tmmcr.race_flag || tmmcei.email_flag || tmmcgi.sex_flag
  ) AS clean_rule_flag, /* ,id.primary_identification_type -- 20250313 */ /* ,mn.primary_identification_no */ /* ,replace(id.secondary_identification_type, '@[]', '') as secondary_identification_type -- 20250620 */ /* ,replace(id.secondary_identification_no, '@[]', '') as secondary_identification_no -- 20250620 */ /* ,mn.customer_name */
  cn.customer_name_concatenate,
  cn.client_name,
  cn.client_name1,
  cn.client_name2,
  cn.client_name3,
  tel.mobile_no,
  tel.fax_no,
  tel.tel_no_home,
  tel.tel_no_office,
  dob.date_of_birth,
  tmmcr.race,
  tmmcei.einvoice_email /* 20250903 einvoice_email */,
  tmmcei.email_1,
  tmmcei.email_2,
  tmmcei.email_3,
  tmmcei.email_4,
  tmmcei.email_5,
  tmmcei.email_6,
  tmmcei.email_7,
  tmmcei.email_8,
  tmmcei.email_9,
  tmmcei.email_10,
  tmmcgi.sex
FROM ${com_schema}.temp_t_mhbos_m_client_identification_info AS id
LEFT JOIN ${com_schema}.temp_t_mhbos_m_client_customer_name_2 AS cn
  ON id.client_no = cn.client_no
LEFT JOIN ${com_schema}.temp_t_mhbos_m_client_telephone_number_info AS tel
  ON id.client_no = tel.client_no
LEFT JOIN ${com_schema}.temp_t_mhbos_m_client_dob_info AS dob
  ON id.client_no = dob.client_no
LEFT JOIN ${com_schema}.temp_t_mhbos_m_client_race_info AS tmmcr
  ON id.client_no = tmmcr.client_no
LEFT JOIN ${com_schema}.temp_t_mhbos_m_client_email_info AS tmmcei
  ON id.client_no = tmmcei.client_no
LEFT JOIN ${com_schema}.temp_t_mhbos_m_client_gender_info AS tmmcgi
  ON id.client_no = tmmcgi.client_no;